-- Originally generated by tools/build-rosie.mjs (not in this repository); edited directly.
local movement=require('rosie.movement') -- QQT_Warpigz_v3 1.0.35: status() for the walk line
local pathfinder=movement.for_owner('town')
local BatmobilePlugin=nil -- Rosie owns native movement.
-- QQT_Warpigz_v3 1.0.25 (stash passes): deposits go in passes, like
-- SteroidAlfred's stash task. Once the stash reads open, one pass every
-- PASS_GAP s sends a move for EVERY item Rosie stashes; the bag decides what
-- moved (a receipt per bag:SNO key) and whatever did not move is sent again on
-- the next pass. Live 3.3.6 (owner, every trip): the panel showed the
-- inventory while the stash list was still loading (stash_n=16, then 293); the
-- one move sent then was dropped by the game, Rosie waited 8 s for its receipt
-- and skipped that SNO for the whole trip, so both Mythic Furnaces stayed in
-- the bag.
-- QQT_Warpigz_v3 1.0.25 (stash passes, review): the stash reads full only at
-- settings.max_stash_items (SteroidAlfred, 3.3.6). An item left in the bag is
-- never a full stash: a refused item, a stale bag entry or a list still
-- loading latched a false permanent "stash full" (stuck, trips refused for
-- 600 s). What the stash did not take is left for this trip (status.lua: a
-- retryable failure while a bag need remains); nothing taken at all is a
-- retryable failure (MAX_FAIL_STREAK latches).
local utils = require 'rosie.private.town.core.utils'
local settings = require 'rosie.private.town.core.settings'
local tracker = require 'rosie.private.town.core.tracker'
local explorerlite = require 'rosie.private.town.core.explorerlite'
local vendor = require 'rosie.private.town.core.vendor'
local events = require 'rosie.private.qqt_events' -- QQT_Warpigz_v3
local mythic_form = require 'rosie.private.mythic_form'
local CarryOnce = require('rosie.data.carry_once')
local task = require('rosie.private.town.tasks.base').new_task()
local plugin_label = 'alfred_the_butler'
local state

task.name = 'stash'
task.status_enum = {
    IDLE = 'Idle', MOVING = 'Moving to stash', INTERACTING = 'Opening stash',
    EXECUTE = 'Depositing into stash', FAILED = 'Failed to stash',
}
-- QQT_Warpigz_v3 1.0.25 (stash passes): the bounds.
-- PASS_GAP: SteroidAlfred's debounce between passes, kept on average (a pass
-- that fires late on the 0.3 s tick does not push the next one back).
-- COUNT_STABLE: a stash count > 0 unchanged this long reads open. INV_HOLD:
-- the inventory panel up this long while the count is 0, unreadable or cached
-- reads open (an empty stash). PROBE_AFTER: one probe per interaction on a
-- host that raised no signal at all. FIRST_WAIT / SECOND_WAIT /
-- AFTER_DEPOSIT: idle passes (no receipt, no stash count change) before a
-- stall, while nothing moved yet (about 12 s: the live load took up to about
-- 8 s) / after the first stall / once anything moved. RECEIPT_IDLE: idle
-- passes after which a panel only a receipt proved open is opened again.
-- QUIET_LINE: while nothing moves, one progress line every this many passes.
-- SKIP_LINES and NAMES cap the log lines and the names in a reason.
-- QQT_Warpigz_v3 1.0.25 (review 2): THIN: after QUIET_LINE passes in which
-- nothing moved and the count stood still, a pass sends only THIN items (in
-- turn over the list) until something moves or the count changes (a stash
-- that refuses everything is not sent every item every second).
-- LEAVE_KEYS: a stash that read open by its list or vendor screen and took
-- nothing leaves at most this many kinds of item for the trip instead of
-- failing it (3.3.6 skipped up to MAX_SKIPS-1=2 before failing).
local C={PASS_GAP=1.0,COUNT_STABLE=0.5,INV_HOLD=1.5,PROBE_AFTER=2.0,FIRST_WAIT=12,SECOND_WAIT=5,
    AFTER_DEPOSIT=3,RECEIPT_IDLE=2,QUIET_LINE=3,THIN=2,LEAVE_KEYS=2,NO_PROGRESS=45,MAX_INTERACTIONS=4,
    INTERACT_GAP=3,BURST=2,SKIP_LINES=5,NAMES=10}
task.C=C

local function log(message) console.print('[Rosie:stash] '..message) end
local function release_movement()
    if BatmobilePlugin then BatmobilePlugin.clear_target(plugin_label) end
    explorerlite:clear_path_and_target()
    pathfinder.clear_stored_path()
end

function task.reset_session()
    -- QQT_Warpigz_v2 local patch (Rosie 1.0.7): stash session evidence.
    -- QQT_Warpigz_v3 1.0.25 (stash passes): the pass state; ledger[key] =
    -- {name, sno, bag, units, dest, sent_at, host, via} per bag:SNO key sent;
    -- count_max: the highest stash count read this session (the reasons never
    -- quote a partial list below it).
    -- QQT_Warpigz_v3 1.0.25 (review 2): gear_moved: receipts from the gear
    -- bags (equipment and talismans land in the stash list, which may still be
    -- loading; gems, runes and materials may not); ready_inv: the inventory
    -- panel was up when the stash read open; quiet: passes since the last
    -- receipt or count change (the stall does not reset it); rot: the
    -- thinned passes' turn.
    state = { time=0, progress=0, next_action=0, next_interact=0, interactions=0, interacted=false,
        interacted_at=0, burst_until=0, base=nil, open_logged=nil, near_since=nil,
        ready=nil, ready_at=nil, ready_inv=false, count_n=nil, count_since=nil, inv_since=nil, lost=0, probe_sent=false,
        next_pass=0, passes=0, idle=0, quiet=0, rot=0, stalls=0, deposited=0, gear_moved=0, last_count=nil,
        count_max=nil, first_logged=false, ledger={}, keys={}, requested={}, noted={}, qty_now={} }
    tracker.stash_skipped=nil -- QQT_Warpigz_v3 (Q5): names read by tasks/status.lua
    task.set_status(task.status_enum.IDLE)
end
function task.suspend()
    if state then state.last_tick=nil end
end
task.reset_session()

local function eligible(item)
    return item~=nil and (not settings.skip_favorite or not item:is_locked())
end
local function should_stash_item(item)
    if not eligible(item) then return false end
    return not utils.is_salvage_or_sell(item,utils.item_enum.SELL)
        and not utils.is_salvage_or_sell(item,utils.item_enum.SALVAGE)
        and not (settings.skip_cache and utils.get_item_type(item)=='cache')
end

local function units(item)
    local n=item:get_stack_count()
    if type(n)~='number' or n~=n or n<0 or n==math.huge then return nil end
    return math.max(1,n) -- Non-stackable host items may report zero.
end

-- QQT_Warpigz_v3 (Q5): one item never stops the stash. An item that raises
-- or cannot be read is passed over (logged once per trip).
local function note(key,message)
    if state.noted[key] then return false end
    state.noted[key]=true
    log(message)
    return true
end
local function remember_skip(name)
    local list=tracker.stash_skipped or {}
    list[#list+1]=tostring(name)
    tracker.stash_skipped=list
end
-- QQT_Warpigz_v3 (Q9 stash follow-up): a one-per-character Splinter of the
-- Prime Evils (rosie/data/carry_once.lua must_keep, or its item skin for a
-- later build's SNO) cannot be stashed: the game refuses the deposit. It is
-- never a candidate; logged once per session.
local kept_noted={}
local function must_keep(item,sno)
    local known=CarryOnce.by_id[sno]
    local name=known and known.must_keep and known.name
    if not known then
        local ok,skin=pcall(function() return item:get_skin_name() end)
        if ok and type(skin)=='string' then
            for _,prefix in ipairs(CarryOnce.skins or {}) do
                if skin:find(prefix,1,true) then name=skin; break end
            end
        end
    end
    if not name then return false end
    if not kept_noted[sno] then
        kept_noted[sno]=true
        log('Kept '..tostring(name)..' in the bag: the game does not stash it.')
    end
    return true
end
local function consumable_check(item)
    if not eligible(item) then return false end
    local ok,sno=pcall(function() return item:get_sno_id() end)
    return not (ok and type(sno)=='number' and must_keep(item,sno))
end
local function key_check(item)
    local sigil=string.lower(item:get_name() or ''):match('dungeonsigil')
    return eligible(item) and (not sigil or tracker.stash_sigils and item:is_locked())
end
local function talisman_check(item)
    return eligible(item) and not utils.should_salvage_talisman(item) and not utils.should_sell_talisman(item)
end

-- QQT_Warpigz_v3 1.0.25 (stash passes): the bags a pass sends from, in
-- tie-break order (Rosie's keep decisions, unchanged); the flags come from
-- tasks/status.lua at trip start. rank: the pass order of a bag's items (gear
-- bags promote Mythics, see rank() below).
local BAGS={
    {bag='get_inventory_items',check=should_stash_item,rank=2,gear=true},
    {bag='get_talisman_items',check=talisman_check,rank=3,gear=true,
        on=function() return tracker.stash_talisman_seal or tracker.stash_talisman_charm end},
    {bag='get_consumable_items',check=consumable_check,rank=4,on=function() return tracker.stash_boss_materials end},
    {bag='get_dungeon_key_items',check=key_check,rank=5,on=function() return tracker.stash_keys end},
    {bag='get_socketable_items',check=eligible,rank=6,on=function() return tracker.stash_socketables end},
}
-- QQT_Warpigz_v3 1.0.25 (stash passes): one read of every bag per tick. Each
-- item's SNO and stack count are read once (Q5 review: an expiring wrapper is
-- never read twice in a frame); the per-bag quantities (the receipts) come
-- from this read, and so do the candidates when `full` is set. A bag whose
-- read raises is skipped this tick (err: the step cannot finish on it); an
-- entry whose SNO or count cannot be read is left out of that SNO's quantity.
-- QQT_Warpigz_v3 1.0.25 (review): the keep decisions (full) run only while the stash is not
-- open or when a pass is due; the other ticks read SNOs and stack counts only.
local function snapshot(player,full)
    local snap={list={},qty={},err=false}
    for bi,spec in ipairs(BAGS) do
        if not spec.on or spec.on() then
            local ok,items=pcall(function() return player[spec.bag](player) end)
            if not ok or type(items)~='table' then
                snap.err=true
                note('bag:'..spec.bag,'Could not read '..spec.bag..' this tick; the stash waits for it.')
            else
                local qty={}
                snap.qty[spec.bag]=qty
                local idx=0
                for _,item in pairs(items) do
                    idx=idx+1
                    local okm,sno,amount=pcall(function() return item:get_sno_id(),units(item) end)
                    local good=okm and type(sno)=='number' and sno>0 and amount~=nil
                    if good then qty[sno]=(qty[sno] or 0)+amount end
                    local okc,take=true,false
                    if full then okc,take=pcall(spec.check,item) end
                    if not okc then
                        local okn,name=pcall(function() return item:get_name() end)
                        if note('raise:'..tostring(take),'Skipped '..tostring(okn and name or 'an item')..' for this trip: its checks raised ('
                            ..tostring(take)..'). The stash goes on with the next item.') then
                            remember_skip(okn and name or 'an unreadable item')
                        end
                    elseif take then
                        if not good then
                            if note('meta:'..spec.bag..':'..tostring(okm and sno),'Skipped an item in '..spec.bag
                                ..' for this trip: SNO or stack count unreadable. The stash goes on with the next item.') then
                                remember_skip('an unreadable item')
                            end
                        else
                            -- The name is only a label (a raising get_name() never stops the stash).
                            local okn,name=pcall(function() return item:get_name() end)
                            if not okn or name==nil then name='sno '..tostring(sno) end
                            snap.list[#snap.list+1]={item=item,bag=spec.bag,key=spec.bag..':'..sno,sno=sno,
                                name=tostring(name),bi=bi,idx=idx,base=spec.rank,gear=spec.gear}
                        end
                    end
                end
            end
        end
    end
    return snap
end
-- QQT_Warpigz_v3 1.0.25 (stash passes): Mythics first, so they take the free
-- slots when space is short (rank 0: iconic or Mythic form, 1: other Uniques,
-- then the bag's own rank).
local function rank(c)
    if not c.gear then return c.base end
    local ok,r=pcall(function()
        local rarity=c.item:get_rarity()
        if type(rarity)~='number' then return c.base end
        if rarity>=8 or utils.mythics[c.sno]~=nil or mythic_form.is_mythic_sno(c.sno)
            or rarity==6 and mythic_form.has_mark(c.item) then return 0 end
        if rarity==6 then return 1 end
        return c.base
    end)
    return ok and type(r)=='number' and r or c.base
end
-- A total order (rank, bag, index in the host list): Lua 5.4's table.sort
-- requires one.
local function order(list)
    for _,c in ipairs(list) do c.rank=rank(c) end
    table.sort(list,function(a,b)
        if a.rank~=b.rank then return a.rank<b.rank end
        if a.bi~=b.bi then return a.bi<b.bi end
        return a.idx<b.idx
    end)
    return list
end
-- Units per SNO in the stash list (false: an entry of that SNO has an
-- unreadable count), or nil when the list cannot be read.
local function stash_qty(player)
    local ok,out=pcall(function()
        local q,bad={},{}
        for _,item in pairs(player:get_stash_items()) do
            local okid,id=pcall(function() return item:get_sno_id() end)
            if okid and type(id)=='number' then
                local okn,n=pcall(units,item)
                if okn and n then q[id]=(q[id] or 0)+n else bad[id]=true end
            end
        end
        for id in pairs(bad) do q[id]=false end
        return q
    end)
    if ok and type(out)=='table' then return out end
end
local function stash_units(dest,sno)
    if dest==nil then return false end
    local d=dest[sno]
    if d==nil then return 0 end
    return d
end
-- Names grouped by key with counts ("X x2"), capped at NAMES, then "(+N more)".
local function names_of(list)
    local seen,keys,out={},{},{}
    for _,c in ipairs(list) do
        local e=seen[c.key]
        if not e then e={name=c.name,sno=c.sno,n=0}; seen[c.key]=e; keys[#keys+1]=c.key end
        e.n=e.n+1
    end
    for i,key in ipairs(keys) do
        if i>C.NAMES then out[#out+1]='(+'..(#keys-C.NAMES)..' more)'; break end
        local e=seen[key]
        out[#out+1]=e.name..(e.n>1 and ' x'..e.n or '')
    end
    return table.concat(out,', '),keys,seen
end

-- QQT_Warpigz_v2 local patch (live 2.3.0-rc.8/rc.9): the stash chest is not
-- an NPC vendor. Signals count only after this stash session interacted with
-- the chest (a Blacksmith panel left open by the repair is not the stash); a
-- signal already up before the first interaction (state.base, review rc.10)
-- proves nothing.
-- QQT_Warpigz_v3 1.0.25 (stash passes): the raw signals after the baseline
-- vetoes (core/vendor.lua stash_signals stays as it is for stash_pull);
-- readiness() below applies the timing. count_ok is false when the stash list
-- was already readable before the first interaction (cached).
local function try(fn)
    local ok,value=pcall(fn)
    if ok then return value end
end
local function stash_read(base)
    local sdk,skin=vendor.sdk_open(),vendor.current_skin()
    local inv=try(function() return is_inventory_open() end)==true
    local n=try(function() return #get_local_player():get_stash_items() end)
    if type(n)~='number' then n=nil end
    local other=skin~=nil and skin~=utils.npc_enum.STASH
    local b=type(base)=='table' and base or {}
    return {sdk=sdk and not other and not b.sdk,inv=inv and not b.inv,n=n,count_ok=not (b.n and b.n>0),
        diag=string.format('sdk=%s inv=%s vendor=%s stash_n=%s',tostring(sdk),tostring(inv),tostring(skin),tostring(n))}
end
local function diag_now() return stash_read(nil).diag end

local function stash_actor()
    local best,best_distance,selected=nil,math.huge,nil
    local best_rank=math.huge
    local origin=get_player_position()
    local function scan(list)
        for _,actor in pairs(list or {}) do
            local ok,pos,id=pcall(function()
                if actor:get_skin_name()~=utils.npc_enum.STASH then return nil end
                return actor:get_position(),actor:get_id()
            end)
            if ok and pos and (pos:x()~=0 or pos:y()~=0 or pos:z()~=0) then
                local distance=origin:dist_to(pos)
                -- QQT_Warpigz_v2 local patch: prefer a chest the host reports
                -- interactable (TristramLoop, MaidenFarmer, WonderCity); never
                -- require it.
                local okf,flag=pcall(function() return actor:is_interactable() end)
                local r=(okf and flag==false) and 1 or 0
                if state.actor_id and id==state.actor_id then selected=actor end
                if r<best_rank or r==best_rank and distance<best_distance then
                    best,best_distance,best_rank=actor,distance,r
                end
            end
        end
    end
    scan(actors_manager:get_all_actors()); scan(get_actors_list())
    local actor=selected or best
    if actor then
        state.actor_id=actor:get_id()
        local pos=actor:get_position()
        state.position=vec3:new(pos:x(),pos:y(),pos:z())
    end
    return actor
end

local function fail(reason)
    release_movement()
    tracker.stash_failed=true
    tracker.failure_reason='Stash: '..reason
    task.set_status(task.status_enum.FAILED)
    log(reason)
end
local function finish()
    release_movement()
    tracker.stash_done=true
    task.set_status(task.status_enum.IDLE)
    -- QQT_Warpigz_v3 (Q5): name what this trip skipped.
    local skipped=tracker.stash_skipped and #tracker.stash_skipped>0
        and ' Skipped for this trip: '..table.concat(tracker.stash_skipped,', ')..'.' or ''
    log('All selected deposits observed; continuing town service.'..skipped)
end
local function unready()
    state.ready,state.interacted,state.open_logged,state.ready_inv=nil,false,nil,false
    state.count_n,state.count_since,state.inv_since,state.lost=nil,nil,nil,0
end
-- The highest stash count read this session, for the reasons.
local function most()
    return state.count_max and 'its list read up to '..state.count_max..' item(s)' or 'its list was unreadable'
end
-- QQT_Warpigz_v3 1.0.25 (stash passes, review): what the stash did not take
-- stays in the bag for this trip: named (SKIP_LINES lines, then a summary),
-- kept in tracker.stash_skipped, and the step ends. tasks/status.lua turns a
-- bag need that remains into a retryable failure, never the permanent latch.
local function leave(list,why)
    local _,keys,seen=names_of(list)
    for i,key in ipairs(keys) do
        local e=seen[key]
        if i<=C.SKIP_LINES then
            log('Skipped '..e.name..' (sno='..tostring(e.sno)..') for this trip: '..why..'.')
        end
        remember_skip(e.name..(e.n>1 and ' x'..e.n or ''))
    end
    if #keys>C.SKIP_LINES then log('Skipped '..(#keys-C.SKIP_LINES)..' more item(s) for this trip (listed below).') end
    finish()
end

-- QQT_Warpigz_v3 1.0.25 (stash passes): receipts. The bag decides: a key's
-- units in its bag fell since the last read. A key's units only ever go down
-- (a low-water mark): Rosie's passes are the only thing that takes items out
-- of the bag during the step, and a bag read that flaps can then never reset
-- the stall and 45 s bounds forever.
local function observe(player,snap)
    local dest,scanned=nil,false
    for _,key in ipairs(state.keys) do
        local L=state.ledger[key]
        local qty=snap.qty[L.bag]
        local now=qty and (qty[L.sno] or 0)
        if now and now<L.units then
            if not scanned then dest,scanned=stash_qty(player),true end
            local d=stash_units(dest,L.sno)
            local delta=(d~=false and L.dest~=false) and string.format('%+.0f',d-L.dest) or 'unreadable'
            -- QQT_Warpigz_v3 1.0.25 (review): the move that worked (live check: host=).
            log(string.format('Deposited %s (sno=%s); %.0f of %.0f unit(s) left the bag (stash list %s); last sent on %s, host=%s.',
                L.name,tostring(L.sno),L.units-now,L.units,delta,tostring(L.via),tostring(L.host)))
            events.emit('rosie','stashed',{name=L.name,sno=L.sno,bag=L.bag}) -- QQT_Warpigz_v3
            L.units,L.dest=now,d
            state.deposited=state.deposited+1; state.progress=state.time; state.idle=0; state.quiet=0
            if L.gear then state.gear_moved=state.gear_moved+1 end
            if not state.first_logged then
                state.first_logged=true
                -- The live measure of the load delay.
                if state.passes>=2 then
                    log(string.format('The stash took the first item on pass %d (%.1fs after it read open).',
                        state.passes,state.time-(state.ready_at or state.time)))
                end
            end
            -- QQT_Warpigz_v2 local patch (Rosie 1.0.7): a deposit probe's
            -- receipt proves the panel open. QQT_Warpigz_v3 1.0.25 (review): only a move sent
            -- after this interaction (a late receipt of an earlier one proves
            -- nothing about the panel now).
            if not state.ready and state.interacted and (L.sent_at or -math.huge)>=state.interacted_at then
                state.ready,state.ready_at,state.lost,state.open_logged='receipt',state.time,0,state.interactions
                state.ready_inv=false
                log('Stash reads open: signal=receipt attempt='..state.interactions..' '..diag_now())
            end
            state.interactions=0
        end
    end
end

-- QQT_Warpigz_v3 1.0.25 (stash passes): when the stash counts as open,
-- checked every tick after this session's interaction: (a) the vendor-screen
-- flag; (b) a stash count > 0 unchanged for COUNT_STABLE (SteroidAlfred:
-- equal on two consecutive checks; a loading list changes and restarts the
-- timer); (c) the inventory panel held for INV_HOLD while the count is 0,
-- unreadable or cached (an empty stash). Once open, the deciding raw signal
-- missing for 2 ticks reads closed. QQT_Warpigz_v3 1.0.25 (review): a panel only a receipt
-- proved open (no signal at all) reads closed after RECEIPT_IDLE idle passes,
-- so Rosie walks back and opens it again instead of passing into nothing.
-- QQT_Warpigz_v3 1.0.25 (review 2): a stash that read open by its count
-- while the inventory panel was up stays open only while that panel is up
-- (the owner's host: inv=true while the stash is open). A list that stays
-- readable after the panel closed (cached) no longer keeps Rosie passing into
-- a closed panel; a list that reads 0 for a moment under an open panel does
-- not close it.
local function readiness()
    local r=stash_read(state.base)
    if state.ready then
        local still
        if state.ready=='count' and r.inv then state.ready_inv=true end -- the panel came up after the count
        if state.ready=='receipt' then still=state.idle<C.RECEIPT_IDLE
        elseif state.ready=='count' and state.ready_inv then still=r.inv
        else
            still=state.ready=='sdk' and r.sdk or state.ready=='inv' and r.inv
                or state.ready=='count' and (r.n or 0)>0
        end
        if still then state.lost=0 else state.lost=state.lost+1 end
        if state.lost>=2 then
            if state.ready=='receipt' then
                log('Nothing left the bag in '..C.RECEIPT_IDLE..' passes on a panel only a receipt proved open ('..r.diag
                    ..'); opening it again.')
            else
                log('Stash panel reads closed ('..r.diag..'); opening it again.')
            end
            unready()
            return false,r
        end
        return true,r
    end
    local counted=r.count_ok and r.n~=nil and r.n>0
    local why=r.sdk and 'sdk' or nil
    if counted then
        if r.n~=state.count_n then state.count_n,state.count_since=r.n,state.time
        elseif state.time-state.count_since>=C.COUNT_STABLE then why=why or 'count' end
    else state.count_n,state.count_since=nil,nil end
    if r.inv and not counted then
        state.inv_since=state.inv_since or state.time
        if state.time-state.inv_since>=C.INV_HOLD then why=why or 'inv' end
    else state.inv_since=nil end
    if not why then return false,r end
    state.ready,state.ready_at,state.lost,state.idle,state.ready_inv=why,state.time,0,0,r.inv
    if state.open_logged~=state.interactions then
        state.open_logged=state.interactions
        log('Stash reads open: signal='..why..' attempt='..state.interactions..' '..r.diag)
    end
    return true,r
end

-- One move per candidate, pcall-guarded and sent directly: vendor_action
-- requires the vendor-screen flag, which the stash panel may not raise. No
-- per-item receipt wait; the ledger entry is made on the key's first send.
local function send(c,probe,dest)
    local L=state.ledger[c.key]
    if not L then
        L={name=c.name,sno=c.sno,bag=c.bag,gear=c.gear,units=(state.qty_now[c.bag] or {})[c.sno] or 0,
            dest=stash_units(dest,c.sno)}
        state.ledger[c.key]=L
        state.keys[#state.keys+1]=c.key
    end
    local called,result=pcall(loot_manager.move_item_to_stash,c.item)
    local host=tostring(called and result or false)
    L.sent_at,L.host,L.via=state.time,host,probe and 'the probe' or 'pass '..state.passes
    tracker.last_task=task.name
    if probe or not state.requested[c.key] then
        state.requested[c.key]=true
        log('Deposit requested: '..c.name..' (sno='..c.sno..', pass='..state.passes..', host='
            ..host..(probe and ', probe=true' or '')..').')
    end
end

-- QQT_Warpigz_v3 1.0.25 (stash passes): idle passes ran out. Nothing moved
-- yet: a stash whose list or vendor screen still reads open gets SECOND_WAIT
-- more passes as it is (review: interacting with the open chest again may
-- restart a long load); otherwise it is opened again once. Nothing moved
-- after that: a retryable failure. Anything moved: the rest stays in the bag
-- for this trip. Returns true when this pass must not be sent.
-- QQT_Warpigz_v3 1.0.25 (review): never tracker.stash_full here (see the header).
-- QQT_Warpigz_v3 1.0.25 (review 2):
-- - proven: the stash took something of what is left: any receipt when no
--   gear is left, a gear receipt when gear is left. A gem or material that
--   went to the materials storage while the stash list still loaded proves
--   nothing about the gear (live model: gear moves are dropped until the list
--   loaded); the gear keeps the long windows.
-- - The first stall waits as it is on any panel signal that still reads open
--   (count, vendor screen and now the inventory panel: a list that reads 0
--   while it loads). Only a panel a receipt alone proved open is opened again.
-- - Nothing moved at all on a stash that read open by its list or vendor
--   screen, and at most LEAVE_KEYS kinds of item left: they are left for this
--   trip (3.3.6 skipped them too). One item the game refuses that is the only
--   candidate of every trip no longer fails every trip.
local function stall(list,count,proven)
    if not proven and state.stalls==0 then
        state.stalls=1; state.idle=0
        if state.ready~='receipt' then
            log(string.format('%s in %d passes; the stash still reads open (signal=%s, stash_n=%s): %d more passes.',
                state.deposited>0 and 'No equipment moved' or 'Nothing moved',state.passes,tostring(state.ready),
                tostring(count),C.SECOND_WAIT))
            return false
        end
        log(string.format('Nothing moved in %d passes; opening the stash again.',state.passes))
        unready(); state.next_interact=math.min(state.next_interact,state.time)
        return true
    end
    local why=string.format('the stash did not take it in %d passes (%s)',state.passes,most())
    if state.deposited==0 then
        local _,keys=names_of(list)
        if #keys<=C.LEAVE_KEYS and (state.ready=='count' or state.ready=='sdk') then
            leave(list,why)
            return true
        end
        fail(string.format('The stash took nothing in %d passes (full or not open? %s); still in the bag: %s. %s',
            state.passes,most(),(names_of(list)),diag_now()))
        return true
    end
    leave(list,why)
    return true
end

-- QQT_Warpigz_v3 1.0.25 (stash passes): one pass. Never into an NPC panel
-- that read open before the chest interaction (review rc.10 R-F8). An idle
-- pass: no receipt and no stash count change since the previous pass (a
-- loading list changes the count, so a slow load never ends the step).
-- QQT_Warpigz_v3 1.0.25 (review 2): the short AFTER_DEPOSIT window only once
-- the stash proved it takes what is left and FIRST_WAIT passes went by (a
-- receipt early in a long load, even a false one from a bag read that flaps,
-- no longer ends the step while the list still loads). After QUIET_LINE
-- quiet passes only THIN items per pass, in turn, until something moves or
-- the count changes.
local function pass(player,list,count)
    if vendor.npc_panel_held(state.base) then return end
    if count~=state.last_count then state.last_count=count; state.idle=0; state.quiet=0 end
    order(list)
    local gear=false
    for _,c in ipairs(list) do if c.gear then gear=true; break end end
    local proven=state.deposited>0 and (state.gear_moved>0 or not gear)
    local window=proven and state.passes>=C.FIRST_WAIT and C.AFTER_DEPOSIT
        or (state.stalls==0 and C.FIRST_WAIT or C.SECOND_WAIT)
    if state.idle>=window and stall(list,count,proven) then return end
    local sending=list
    if state.quiet>=C.QUIET_LINE and #list>C.THIN then
        sending={}
        for i=1,C.THIN do sending[i]=list[(state.rot+i-1)%#list+1] end
        state.rot=state.rot+C.THIN
    end
    -- QQT_Warpigz_v3 1.0.25 (review): a stalled load is not silent in the log.
    if state.quiet>0 and state.quiet%C.QUIET_LINE==0 then
        log(string.format('Pass %d: nothing has left the bag in %d pass(es); sending %d of %d item(s) again (stash_n=%s).',
            state.passes+1,state.quiet,#sending,#list,tostring(count)))
    end
    state.passes=state.passes+1; state.idle=state.idle+1; state.quiet=state.quiet+1
    local dest=stash_qty(player) -- one stash scan per pass
    for _,key in ipairs(state.keys) do
        local L=state.ledger[key]
        L.dest=stash_units(dest,L.sno)
    end
    for _,c in ipairs(sending) do send(c,false,dest) end
end

-- QQT_Warpigz_v3 1.0.35 (owner live 3.3.24, Temis: "after salvaging it
-- tries to go to the stash but gets stuck at the Blacksmith"; the log had no
-- "Open stash" line, then "No stash progress for 45 active seconds"): the walk
-- to the chest had no stuck recovery. rosie/movement.lua blocks a goal after
-- about 9 s without progress ('Stopped: no movement progress') and keeps it
-- blocked until the owner releases it; the base tasks reset on a stall
-- (tasks/base.lua), the stash walk never did, so one stall at the Blacksmith
-- (body-blocked at the counter, another mover's command) stood still until
-- the 45 s failure. Now: WALK.STALL s without 0.4 m of progress releases the
-- movement (which clears the block) and walks on, in turn: a plain re-request,
-- the town's default reset point (Temis: the portal, beside the Blacksmith and
-- the chest), WALK.SIDE m to one side, then the other side, then again. The
-- walk is logged when it starts, every WALK.LOG_GAP s and on each stall: the
-- target, where it came from (the chest actor or the town table), the
-- distance, the player and the movement status, so the next live log names
-- the Temis chest position and why the walk stands.
-- QQT_Warpigz_v3 1.0.36 (owner live 3.3.25, Temis, after a Reaper run): the
-- 1.0.35 recovery ran (stalls 1-4, detours) but the player moved about 1 m in
-- 22 s and reached not even the portal point, so the move requests did not
-- move the player at all (another mover's command kept, or the host skipping
-- request_move). The stash walk uses rosie/movement.lua like the base tasks
-- (BatmobilePlugin is nil in this file); the 1.0.35 lines read move=Idle
-- because they were printed right after Rosie's own release. Now:
--  * after a stall the walk opens movement.force_for('town'), so a request
--    the host skips is sent once more with force_move_raw (rosie/movement.lua);
--  * from the first stall, a chest actor within WALK.INTERACT_RANGE m is
--    interacted with every WALK.INTERACT_GAP s (at most WALK.INTERACT_MAX per
--    session; not counted in MAX_INTERACTIONS): the game walks the player to
--    an interacted object; the normal approach takes over within 3 m;
--  * the lines are printed after the request: the request result, the
--    movement status and the player's move destination (dest=, a foreign
--    command shows there).
local WALK={STALL=4,LOG_GAP=10,VIA_REACH=1.5,SIDE=3,INTERACT_RANGE=10,INTERACT_GAP=3,INTERACT_MAX=6}
task.WALK=WALK
local function point(v)
    local ok,x,y,z=pcall(function() return v:x(),v:y(),v:z() end)
    if ok and type(x)=='number' and type(y)=='number' then return {x=x,y=y,z=tonumber(z) or 0} end
    return nil
end
local function flat(a,b) return math.sqrt((a.x-b.x)^2+(a.y-b.y)^2) end
local function detour(n,here,goal)
    local k=(n-1)%4
    if k==0 then return nil end
    if k==1 then
        local okt,town=pcall(utils.get_town)
        local p=okt and type(town)=='table' and type(town.reset_positions)=='table' and point(town.reset_positions.default)
        if p and flat(p,here)>WALK.VIA_REACH and flat(p,goal)>WALK.VIA_REACH then return p end
        k=2
    end
    local dx,dy=goal.x-here.x,goal.y-here.y
    local d=math.sqrt(dx*dx+dy*dy)
    if d<0.01 then return nil end
    local side=k==2 and 1 or -1
    return {x=here.x-dy/d*WALK.SIDE*side,y=here.y+dx/d*WALK.SIDE*side,z=here.z}
end
local function walk_line(head,w,here,goal,distance,sent)
    local okm,st=pcall(movement.status)
    local detail=okm and type(st)=='table' and tostring(st.detail) or '?'
    local via=w.via and string.format(' via=(%.1f,%.1f)',w.via.x,w.via.y) or ''
    local okd,dest=pcall(function() return point(get_local_player():get_move_destination()) end) -- QQT_Warpigz_v3 1.0.36
    local dest_s=okd and dest and string.format('(%.1f,%.1f)',dest.x,dest.y) or 'n/a'
    log(string.format('%s: target=(%.1f,%.1f,%.1f) from=%s distance=%s player=(%.1f,%.1f) request=%s move=%s dest=%s stalls=%d%s',
        head,goal.x,goal.y,goal.z,tostring(w.from),
        distance and string.format('%.1f',distance) or 'n/a',here.x,here.y,tostring(sent),detail,dest_s,w.stalls,via))
end
-- QQT_Warpigz_v3 1.0.36: the game walks the player to an interacted chest.
local function interact_walk(w,actor,distance)
    if w.stalls<1 or not actor or not distance or distance>WALK.INTERACT_RANGE then return end
    if (state.walk_interacts or 0)>=WALK.INTERACT_MAX or state.time<(w.interact_at or -math.huge)+WALK.INTERACT_GAP then return end
    if vendor.npc_panel_held(state.base) then return end
    w.interact_at=state.time
    state.walk_interacts=(state.walk_interacts or 0)+1
    if not state.base then state.base=vendor.stash_baseline() end
    local ok,result=pcall(vendor.interact,actor,'STASH')
    log(string.format('The walk stalls: interacting with the chest at %.1f m so the game walks there (%d of %d, host=%s).',
        distance,state.walk_interacts,WALK.INTERACT_MAX,tostring(ok and result)))
end
local function walk(actor,distance)
    local here=point(get_player_position())
    local source=state.position or utils.get_npc_location('STASH')
    local goal=source and point(source)
    if not here or not goal then return end
    local from=actor and ('chest actor '..tostring(state.actor_id)) or state.position and 'last seen chest' or 'town table'
    local w=state.walk
    if not w then w={at=state.time,pos=here,stalls=0,log_at=-math.huge}; state.walk=w end
    w.from=from
    if (here.x-w.pos.x)^2+(here.y-w.pos.y)^2>=0.16 then w.pos=here; w.at=state.time end
    if w.via and flat(here,w.via)<=WALK.VIA_REACH then w.via=nil end
    local head=nil
    if state.time-w.at>=WALK.STALL then
        w.stalls=w.stalls+1; w.at=state.time
        release_movement() -- clears rosie/movement.lua's block for this goal
        w.via=detour(w.stalls,here,goal)
        head=string.format('No walking progress for %ds; walking on',WALK.STALL)
    elseif state.time>=w.log_at+WALK.LOG_GAP then
        head='Walking to the stash'
    end
    local target=w.via and vec3:new(w.via.x,w.via.y,w.via.z) or utils.compute_move_target(vec3:new(goal.x,goal.y,goal.z))
    if w.stalls>0 then pcall(movement.force_for,'town',1) end -- QQT_Warpigz_v3 1.0.36
    local sent
    if BatmobilePlugin then
        BatmobilePlugin.set_target(plugin_label,target); sent=BatmobilePlugin.move(plugin_label)
    else
        explorerlite:set_custom_target(target); sent=explorerlite:move_to_target()
    end
    if head then w.log_at=state.time; walk_line(head,w,here,goal,distance,sent) end -- QQT_Warpigz_v3 1.0.36: after the request
    interact_walk(w,actor,distance)
end

function task.Execute()
    local player=get_local_player()
    if not player or player:is_dead() or tracker.external_pause then task.suspend(); return end
    local now=get_time_since_inject()
    state.time=state.time+(state.last_tick and math.max(0,now-state.last_tick) or 0)
    state.last_tick=now
    if state.time<state.next_action then return end
    state.next_action=state.time+0.3
    -- QQT_Warpigz_v3 1.0.25 (review): the keep decisions run while the stash is not open and
    -- on pass ticks; the ticks between passes only read the receipts.
    local full=state.ready==nil or state.time>=state.next_pass
    local snap=snapshot(player,full)
    state.qty_now=snap.qty
    observe(player,snap)
    if full and #snap.list==0 and not snap.err then finish(); return end
    if state.time-state.progress>=C.NO_PROGRESS then
        fail('No stash progress for 45 active seconds; check the chest and available space.')
        return
    end
    if full and #snap.list==0 then task.set_status('Waiting for readable bag contents'); return end
    local actor=stash_actor()
    local distance=actor and utils.distance_to(actor)
    local open,r=false,nil
    if state.interacted then open,r=readiness() end
    if open then
        -- The open stash is stronger evidence than a center-distance estimate.
        release_movement(); state.walk=nil -- QQT_Warpigz_v3 1.0.35
        task.set_status(task.status_enum.EXECUTE)
        local count=r.n
        if count then
            tracker.stash_item_count_cached=count
            if count>(state.count_max or -1) then state.count_max=count end
        end
        if state.time>=state.next_pass then
            -- QQT_Warpigz_v3 1.0.25 (review 2): the maximum is checked only
            -- where a pass would send (this tick's candidates are not empty: an
            -- empty list finished above). A last deposit that fills the stash
            -- to the maximum ends the step as done, not "full" (SP17).
            if count and count>=settings.max_stash_items then
                tracker.stash_full=true
                fail(string.format('The stash is full (%d/%d items).',count,settings.max_stash_items))
                return
            end
            -- QQT_Warpigz_v3 1.0.25 (review): PASS_GAP on average (the pass fires on the
            -- first 0.3 s tick after it is due; that delay is not added to
            -- the next one), never closer than half a gap.
            local planned=state.next_pass+C.PASS_GAP
            if planned<state.time+C.PASS_GAP/2 then planned=state.time+C.PASS_GAP end
            state.next_pass=planned
            pass(player,snap.list,count)
        end
        return
    end
    if not full then return end -- the stash read closed on this tick: the next one has the candidates
    -- QQT_Warpigz_v2 local patch (review rc.10): interact at < 2 m like
    -- Alfred and base.lua; within 3 m keep walking to the chest centre, and
    -- interact there only after 1.5 s without reaching 2 m (the chest body).
    local near=actor~=nil and distance<=3
    if not near then state.near_since=nil
    elseif not state.near_since then state.near_since=state.time end
    local reach=near and (distance<2 or state.time-state.near_since>=1.5)
    if reach then
        release_movement(); state.walk=nil -- QQT_Warpigz_v3 1.0.35
        task.set_status(task.status_enum.INTERACTING)
        -- QQT_Warpigz_v3 1.0.25 (stash passes): no deposit and no
        -- re-interaction while the panel is opening (a signal is up but no
        -- open rule fired yet; live: the inventory shows ~0.3 s after the
        -- interaction, long before the stash list loaded).
        if r~=nil and (r.sdk or r.inv or (r.count_ok and (r.n or 0)>0)) then return end
        -- QQT_Warpigz_v2 local patch (Rosie 1.0.7): a host that raised no
        -- signal at all gets one deposit probe per interaction; only its
        -- receipt opens the stash. QQT_Warpigz_v3 1.0.25 (review): each interaction probes
        -- the next candidate (one item the game refuses cannot use them all).
        if state.interacted and not state.probe_sent and state.time-state.interacted_at>=C.PROBE_AFTER
            and not vendor.npc_panel_held(state.base) then
            state.probe_sent=true
            local list=order(snap.list)
            send(list[(math.max(1,state.interactions)-1)%#list+1],true,stash_qty(player))
            return
        end
        if state.time>=state.next_interact then
            if state.probe_sent then log('Deposit probe moved nothing; the stash panel is not open.') end
            if state.interactions>=C.MAX_INTERACTIONS then
                -- QQT_Warpigz_v3 1.0.25 (review): a panel that stops opening after deposits
                -- leaves the rest for this trip, like a stall.
                if state.deposited>0 then
                    leave(order(snap.list),'the stash panel did not open again after '..C.MAX_INTERACTIONS..' interactions')
                    return
                end
                fail('Stash window did not open after '..C.MAX_INTERACTIONS..' interactions. '..diag_now()); return
            end
            state.interactions=state.interactions+1; state.next_interact=state.time+C.INTERACT_GAP
            state.burst_until=state.time+C.BURST; state.interacted_at=state.time; state.probe_sent=false
            if not state.base then state.base=vendor.stash_baseline() end
            local ok,result=pcall(vendor.interact,actor,'STASH') -- QQT_Warpigz_v3 (Q6): a panel Rosie closes
            state.interacted=true
            local okp,x,y=pcall(function() local p=actor:get_position(); return p:x(),p:y() end)
            local okf,flag=pcall(function() return actor:is_interactable() end)
            log(string.format('Open stash: attempt=%d distance=%.1f host=%s actor=(%.1f,%.1f) interactable=%s %s',
                state.interactions,distance,tostring(ok and result),okp and x or 0,okp and y or 0,tostring(okf and flag),
                diag_now()))
        elseif state.time<state.burst_until then
            pcall(vendor.interact,actor,'STASH') -- Alfred re-interacts every tick for 2 s (QQT_Warpigz_v3 Q6)
        end
        return
    end
    task.set_status(task.status_enum.MOVING)
    unready()
    if not near then state.base=nil end
    walk(actor,distance)
end

function task.shouldExecute()
    return utils.is_in_town() and tracker.trigger_tasks and not tracker.stash_failed and not tracker.stash_done
        and (tracker.sell_done or tracker.sell_failed) and (tracker.salvage_done or tracker.salvage_failed)
        and (tracker.salvage_talisman_done or tracker.salvage_talisman_failed)
end
return task
